CREATE   PROCEDURE [bud].[jsGetBudgetInsightAll]      @company INT = 1,      @month   VARCHAR(100) = '11-2025'  AS  BEGIN      SET NOCOUNT ON;        -- ============================================      -- TEMP TABLE 1: ALL users in the company (base list)   [UNCHANGED]      -- ============================================      CREATE TABLE #AllUsers (          userId   INT PRIMARY KEY CLUSTERED,          userName NVARCHAR(201) NOT NULL      );        INSERT INTO #AllUsers (userId, userName)      SELECT          u.userId,          CONCAT(u.firstName, ' ', u.lastName)      FROM jsUser u      INNER JOIN jsUserCompany uc ON uc.userId = u.userId      WHERE uc.companyId = @company;        -- ============================================      -- TEMP TABLE 2: Users with their valid stages          [UNCHANGED]      -- ============================================      CREATE TABLE #UserStages (          userId  INT NOT NULL,          stageId INT NOT NULL,          PRIMARY KEY CLUSTERED (userId, stageId)      );        INSERT INTO #UserStages (userId, stageId)      SELECT DISTINCT          u.userId,          jus.stageId      FROM #AllUsers u      INNER JOIN jsUserStage jus       ON jus.userId = u.userId      INNER JOIN jsStageTemplate st    ON jus.stageId = st.stageId      INNER JOIN jsTemplate t          ON st.templateId = t.id      INNER JOIN jsTemplateApproval ta ON t.id = ta.templateId      WHERE t.company = @company        AND ta.approvalId = 5        AND (              (jus.startTime IS NULL AND jus.endDate IS NULL)              OR (                  jus.status = 1 AND                  GETDATE() BETWEEN jus.startTime AND jus.endDate              )            );        -- ============================================      -- TEMP TABLE 3 (NEW): Distinct budget documents that have at least one      -- budget line in @month. Resolves the heavy      --     jsDocEntry -> jsDocEnrtyDetail -> jsBudgetTable      -- join ONE TIME (previously done twice). 'isPending' preserves the original      -- jd.status = 'P' predicate without materialising the raw status column.      -- ============================================      CREATE TABLE #MonthDocs (          docId          INT PRIMARY KEY CLUSTERED,          currentStageId INT NOT NULL,          templateId     INT NOT NULL,          isPending      BIT NOT NULL      );        INSERT INTO #MonthDocs (docId, currentStageId, templateId, isPending)      SELECT DISTINCT          jd.id,          jd.currentStageId,          jd.templateId,          CASE WHEN jd.status = 'P' THEN 1 ELSE 0 END      FROM bud.jsDocEntry jd      INNER JOIN bud.jsDocEnrtyDetail d ON jd.id = d.docId      INNER JOIN bud.jsBudgetTable bt          ON bt.docEntry = jd.docEntry          AND bt.ObjType  = d.objType          AND bt.Branch   = CAST(d.company AS NVARCHAR(200))          AND bt.LineNum  = d.lineNum          AND bt.VisOrder = d.visOrder      WHERE bt.CURRENTMONTH = @month;        -- ============================================      -- TEMP TABLE 4: Pending counts per user      -- Reuses #MonthDocs (pending only). The original "insert then DELETE      -- already-acted rows" is folded into a single NOT EXISTS at read time      -- (identical net set, one fewer TempDB write/delete pass).      -- ============================================      CREATE TABLE #PendingCounts (          userId       INT PRIMARY KEY CLUSTERED,          TotalPending INT NOT NULL DEFAULT 0      );        INSERT INTO #PendingCounts (userId, TotalPending)      SELECT          us.userId,          COUNT(DISTINCT md.docId)      FROM #UserStages us      INNER JOIN #MonthDocs md ON md.currentStageId = us.stageId      WHERE md.isPending = 1        AND NOT EXISTS (              SELECT 1              FROM bud.jsBudgetStatusWorkflow wf              WHERE wf.docId      = md.docId                AND wf.stageId    = md.currentStageId                AND wf.templateId = md.templateId                AND wf.userId     = us.userId        )      GROUP BY us.userId;        -- ============================================      -- TEMP TABLE 5: Approved & Rejected counts (ONE PASS)      -- Reuses #MonthDocs instead of re-joining doc/detail/budget chain.      -- ============================================      CREATE TABLE #ActionCounts (          userId        INT PRIMARY KEY CLUSTERED,          TotalApproved INT NOT NULL DEFAULT 0,          TotalRejected INT NOT NULL DEFAULT 0      );        INSERT INTO #ActionCounts (userId, TotalApproved, TotalRejected)      SELECT          us.userId,          COUNT(DISTINCT CASE WHEN wf.status = 'A' THEN md.docId END),          COUNT(DISTINCT CASE WHEN wf.status = 'R' THEN md.docId END)      FROM #UserStages us      INNER JOIN bud.jsBudgetStatusWorkflow wf          ON wf.stageId = us.stageId          AND wf.userId = us.userId          AND wf.status IN ('A', 'R')      INNER JOIN #MonthDocs md ON md.docId = wf.docId      GROUP BY us.userId;        -- ============================================      -- FINAL OUTPUT: ALL users with their counts            [UNCHANGED]      -- ============================================      SELECT          au.userId   AS UserID,          au.userName AS UserName,          ISNULL(pc.TotalPending, 0)  AS TotalPending,          ISNULL(ac.TotalApproved, 0) AS TotalApproved,          ISNULL(ac.TotalRejected, 0) AS TotalRejected,          'Budget' AS type      FROM #AllUsers au      LEFT JOIN #PendingCounts pc ON au.userId = pc.userId      LEFT JOIN #ActionCounts  ac ON au.userId = ac.userId      ORDER BY au.userName;        -- Cleanup      DROP TABLE #AllUsers;      DROP TABLE #UserStages;      DROP TABLE #MonthDocs;      DROP TABLE #PendingCounts;      DROP TABLE #ActionCounts;  END;
